-- stg_mc_packages_active: part 1 of 1, 86 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_packages_active (
  tag text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_packages_active enable row level security;
drop policy if exists stg_mc_packages_active_read on public.stg_mc_packages_active;
create policy stg_mc_packages_active_read on public.stg_mc_packages_active for select to authenticated using (true);
